contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address to, uint256 id) public payable {
        require(to != address(0));

        bool exists;
        try c.ownerOf(id) returns (address o) {
            exists = (o != address(0));
        } catch {
            exists = false;
        }

        bool reverted;
        if (exists && from == _ownerOfForTest(id)) {
            try c.transferFrom(from, to, id) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            reverted = true;
            try c.ownerOf(id) returns (address o2) {
                exists = (o2 != address(0));
            } catch {
                exists = false;
            }
        }

        address afterOwner;
        if (exists) {
            try c.ownerOf(id) returns (address o3) {
                afterOwner = o3;
            } catch {
                afterOwner = address(0);
            }
        } else {
            afterOwner = address(0);
        }

        assert(reverted || (afterOwner == to && afterOwner != address(0)));
    }

    function _ownerOfForTest(uint256 id) internal view returns (address o) {
        try c.ownerOf(id) returns (address ret) {
            return ret;
        } catch {
            return address(0);
        }
    }

    receive() external payable {}
}

