contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address to, uint256 id, bytes calldata data) public {
        require(true);

        bool reverted;

        if (to == address(0)) {
            return;
        }

        try c.safeTransferFrom(from, to, id, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address ownerBefore = address(0);
        bool ownerExists = false;
        try c.ownerOf(id) returns (address owner) {
            ownerBefore = owner;
            ownerExists = true;
        } catch {
            ownerExists = false;
        }

        if (!ownerExists) {
            assert(reverted);
        } else {
            if (from != ownerBefore) {
                assert(reverted);
            } else if (to.code.length != 0) {
                bool authorized = (msg.sender == from) || c.isApprovedForAll(from, msg.sender) || (msg.sender == c.getApproved(id));
                if (!authorized) {
                    assert(reverted);
                }
            }
        }
    }
}

